function quizView(){const c=$('#quiz-content'),quiz=quizzes[currentLang];if(quizStep<quiz.length){const s=quiz[quizStep];c.innerHTML=`<h2 id="quiz-title">${s.q}</h2><p>${s.sub}</p><div class="quiz-progress">${quiz.map((_,i)=>`<i class="${i<=quizStep?'done':''}"></i>`).join('')}</div><div class="quiz-options">${s.opts.map((o,i)=>`<button class="quiz-option" data-answer="${i}"><b>${o[0]}</b><small>${o[1]}</small></button>`).join('')}</div>`}else{const result=answers[0]===1?products[4]:answers[0]===2?products[5]:answers[0]===3?products[1]:products[2],label=currentLang==='ar'?result.ar:result.name;c.innerHTML=`<div class="quiz-result"><img src="assets/products/${result.img}" alt="${label}"><div><span class="section-kicker">${currentLang==='ar'?'تطابق بنسبة 97%':'97% match'}</span><h2 id="quiz-title">${label}</h2><p>${currentLang==='ar'?'اختيار متوازن يناسب إجاباتك ويمنحك حضورًا واضحًا وثباتًا ممتازًا.':'A balanced match for your answers, with excellent presence and longevity.'}</p><b>${money(result.price)}</b><br><button class="btn btn-dark" style="margin-top:18px" data-result-add="${result.id}">${currentLang==='ar'?'أضف للسلة':'Add to bag'}</button></div></div>`}}
