let finderSelections={};
function finderStepIcon(index){return['user','flower','perfume','user','bag','season','sparkles','card'][index]}
function finderProgress(ar,steps){return `<div class="finder-progress">${steps.map((s,i)=>`<button class="${i<quizStep?'done':i===quizStep?'active':''}" data-finder-jump="${i}" ${i>quizStep?'disabled':''}><span>${i<quizStep?'✓':i+1}</span><small>${s.title.replace(/[؟?].*/, '').split(' ').slice(0,3).join(' ')}</small></button>`).join('')}</div>`}
function finderOptionCard(option,step,index){const selected=(finderSelections[quizStep]||[]).includes(option[0]),visual=step.visual,icon=visual?`<img src="assets/products/${products.find(p=>p.id===option[3])?.img||products[index].img}" alt="">`:`<span>${uiIcon(option[3])}</span>`;return `<button class="finder-option ${selected?'selected':''} ${visual?'visual':''}" data-finder-option="${option[0]}" aria-pressed="${selected}">${selected?'<i>✓</i>':''}${icon}<b>${option[1]}</b><small>${option[2]}</small></button>`}
function finderSummary(steps,ar){const completed=steps.map((s,i)=>{const values=finderSelections[i]||[];if(!values.length)return'';const names=values.map(v=>s.options.find(o=>o[0]===v)?.[1]).filter(Boolean).join('، ');return `<div><span>${uiIcon(finderStepIcon(i))}</span><p><b>${s.title.replace(/[؟?]/g,'')}</b><small>${names}</small></p>${i<quizStep?`<button data-finder-jump="${i}">${ar?'تعديل':'Edit'}</button>`:''}</div>`}).join('');const percent=Math.round(((quizStep+1)/steps.length)*100);return `<aside class="finder-summary"><h3>${ar?'ملخص اختياراتك حتى الآن':'Your choices so far'}</h3>${completed||`<p class="finder-summary-empty">${ar?'ستظهر اختياراتك هنا خطوة بخطوة':'Your selections will appear here step by step'}</p>`}<footer><span style="--progress:${percent}%"><b>${percent}%</b></span><p><b>${ar?'أنت على الطريق الصحيح!':'You are on the right track!'}</b><small>${ar?`أكمل ${Math.max(0,steps.length-quizStep-1)} خطوات للحصول على النتائج`:`Complete ${Math.max(0,steps.length-quizStep-1)} steps to see results`}</small></p></footer></aside>`}
const finderProfiles={asad:['men','oriental','oud','amber','bold','work','evening','winter','lasting','strong','luxury'],club:['men','citrus','bergamot','bold','social','travel','evening','strong','value'],khamrah:['unisex','oriental','vanilla','amber','social','special','night','winter','lasting','luxury'],caprice:['men','aromatic','bergamot','calm','classic','work','day','summer','balanced','value'],naque:['unisex','woody','musk','calm','classic','daily','day','summer','safe','balanced'],fakhar:['women','floral','rose','vanilla','social','romantic','special','evening','luxury','lasting']};
function finderRankProducts(){const chosen=Object.values(finderSelections).flat(),budget=Number(finderSelections[7]?.[0]||99999);return products.filter(p=>!p.hidden).map(p=>{const profile=finderProfiles[p.id]||[],hits=chosen.filter(value=>profile.includes(value)).length,budgetScore=budget===99999?5:p.price<=budget?10:-Math.min(12,Math.ceil((p.price-budget)/250)),ratingScore=Math.round((Number(p.rating)-4.5)*8),score=hits*4+budgetScore+ratingScore;return{p,score,match:Math.max(72,Math.min(98,80+score))}}).sort((a,b)=>b.score-a.score||Number(b.p.rating)-Number(a.p.rating)).slice(0,3)}
function finderResults(ar){const ranked=finderRankProducts();return `<div class="finder-results"><span class="finder-kicker">${uiIcon('sparkles')} ${ar?'نتائجك الذكية':'Your smart matches'}</span><h1 id="quiz-title">${ar?'عطور مختارة لتناسب حضورك':'Fragrances selected for your presence'}</h1><p>${ar?'رتبنا النتائج حسب مدى توافقها مع اختياراتك وميزانيتك.':'Results are ranked by compatibility with your choices and budget.'}</p><div class="finder-result-grid">${ranked.map(({p,match},i)=>`<article><em>${match}% ${ar?'تطابق':'match'}</em><img src="assets/products/${p.img}" alt="${ar?p.ar:p.name}"><span>${p.brand}</span><h2>${ar?p.ar:p.name}</h2><div>★ ${p.rating} · ${p.reviews}</div><b>${money(p.price)}</b><button class="btn btn-wine" data-result-add="${p.id}">${ar?'أضف للسلة':'Add to bag'}</button><button class="finder-view" data-quick="${p.id}">${ar?'عرض التفاصيل':'View details'}</button></article>`).join('')}</div><button class="finder-restart" data-finder-restart>${ar?'إعادة الاختبار':'Restart finder'}</button></div>`}
quizView=function(){const ar=currentLang==='ar',steps=finderSteps[currentLang],c=$('#quiz-content');if(quizStep>=steps.length){c.innerHTML=`<div class="finder-header"><button data-close-quiz aria-label="${ar?'إغلاق':'Close'}">×</button><a class="brand"><span class="brand-name">ORIGO</span><span class="brand-sub">SCENTS</span></a><span>${uiIcon('sparkles')} ${ar?'العثور الذكي':'SMART FINDER'}</span></div>${finderProgress(ar,steps)}${finderResults(ar)}`;return}const step=steps[quizStep],selected=(finderSelections[quizStep]||[]).length;c.innerHTML=`<div class="finder-header"><button data-close-quiz aria-label="${ar?'إغلاق':'Close'}">×</button><a class="brand"><span class="brand-name">ORIGO</span><span class="brand-sub">SCENTS</span></a><span>${uiIcon('sparkles')} ${ar?'العثور الذكي':'SMART FINDER'}</span></div>${finderProgress(ar,steps)}<div class="finder-shell"><main class="finder-question"><span class="finder-kicker">${uiIcon(finderStepIcon(quizStep))} ${quizStep+1} / ${steps.length}</span><h1 id="quiz-title">${step.title}</h1><p>${step.sub}</p><div class="finder-option-grid ${step.visual?'audience':''}">${step.options.map((o,i)=>finderOptionCard(o,step,i)).join('')}</div><div class="finder-tip">${uiIcon('sparkles')}<p><b>${ar?'نصيحة ذكية':'Smart tip'}</b><small>${ar?'كلما كانت اختياراتك أدق، أصبحت توصياتنا أكثر ملاءمة لذوقك.':'More precise choices create more accurate recommendations.'}</small></p></div></main>${finderSummary(steps,ar)}</div><div class="finder-actions"><button data-finder-prev ${quizStep===0?'disabled':''}>← ${ar?'السابق':'Previous'}</button><button class="primary" data-finder-next ${selected?'':'disabled'}>${quizStep===steps.length-1?(ar?'عرض النتائج الآن':'Show results'):(ar?'التالي':'Next')} →</button></div>`}
openQuiz=function(){closeSurfaces('quiz');quizStep=0;finderSelections={};quizView();const el=$('.quiz-modal');el.inert=false;el.classList.add('open');el.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';syncOverlay();setTimeout(()=>el.querySelector('[data-finder-option]')?.focus(),30)}
const closeQuizFinderBase=closeQuiz;
closeQuiz=function(){closeQuizFinderBase();document.body.style.overflow=''}
document.addEventListener('click',e=>{const option=e.target.closest('[data-finder-option]');if(option){const step=finderSteps[currentLang][quizStep],value=option.dataset.finderOption,current=finderSelections[quizStep]||[];finderSelections[quizStep]=step.single?[value]:(current.includes(value)?current.filter(v=>v!==value):[...current,value]);quizView();return}const next=e.target.closest('[data-finder-next]');if(next&&!next.disabled){quizStep++;quizView();return}const prev=e.target.closest('[data-finder-prev]');if(prev&&!prev.disabled){quizStep=Math.max(0,quizStep-1);quizView();return}const jump=e.target.closest('[data-finder-jump]');if(jump&&!jump.disabled){quizStep=Number(jump.dataset.finderJump);quizView();return}if(e.target.closest('[data-finder-restart]')){quizStep=0;finderSelections={};quizView()}});
