function alternativeHeader(ar){return `<header class="alternative-header"><button data-close-alternative aria-label="${ar?'إغلاق':'Close'}">×</button><a class="brand"><span class="brand-name">ORIGO</span><span class="brand-sub">SCENTS</span></a><div><button data-open-quiz>${uiIcon('sparkles')} ${ar?'مكتشف العطر':'Fragrance finder'}</button><button class="active">${uiIcon('refresh')} ${ar?'مكتشف البديل':'Alternative finder'}</button></div></header>`}
function alternativeSearchView(ar){return `${alternativeHeader(ar)}<main class="alternative-search-page"><span class="alternative-mark">${uiIcon('search')}</span><h1>${ar?'ابحث عن بديل ذكي لعطرك المفضل':'Find a smart alternative to your favorite fragrance'}</h1><p>${ar?'اكتب اسم العطر الذي تحبه وسنقترح لك أفضل البدائل المتاحة بسعر مناسب.':'Enter a fragrance you love and we will find the best available alternatives.'}</p><form class="alternative-search-form" data-alternative-search><input value="${alternativeQuery}" placeholder="${ar?'مثال: Creed Aventus أو Dior Sauvage':'Example: Creed Aventus or Dior Sauvage'}" aria-label="${ar?'اسم العطر':'Fragrance name'}"><button>${uiIcon('search')} ${ar?'بحث':'Search'}</button></form>${alternativeQuery?alternativeSuggestions(ar):''}<div class="popular-searches"><b>${ar?'اقتراحات شائعة':'Popular searches'}</b>${alternativeQueries.map(q=>`<button data-alt-query="${q}">${q}</button>`).join('')}</div><div class="alternative-showcase"><img src="assets/alternatives/silver-crest-v1.webp" alt=""><span>${uiIcon('refresh')}</span><img src="assets/alternatives/origo-majestic-oud-v1.webp" alt=""></div><div class="alternative-benefits"><div>${uiIcon('shield')}<b>${ar?'بدائل أصلية':'Authentic alternatives'}</b><small>${ar?'منتجات مضمونة ومعتمدة':'Guaranteed products'}</small></div><div>${uiIcon('card')}<b>${ar?'وفّر أكثر':'Save more'}</b><small>${ar?'جودة عالية بسعر أفضل':'Premium quality, better price'}</small></div><div>${uiIcon('sparkles')}<b>${ar?'نتائج ذكية':'Smart results'}</b><small>${ar?'مطابقة مبنية على النوتات والأداء':'Notes and performance matching'}</small></div></div></main>`}
function alternativeSuggestions(ar){const q=alternativeQuery.toLowerCase(),items=alternativeQueries.filter(x=>x.toLowerCase().includes(q)||!q).slice(0,5);return `<div class="alternative-suggestions">${items.map((name,i)=>`<button data-alt-query="${name}"><img src="${i%2?'assets/alternatives/noir-intense-v1.webp':'assets/alternatives/silver-crest-v1.webp'}" alt=""><span><b>${name}</b><small>${i%2?'Designer fragrance':'Reference fragrance'}</small></span>${uiIcon('search')}</button>`).join('')}<button class="show-all" data-alt-submit>${ar?'عرض جميع النتائج':'Show all results'} “${alternativeQuery}”</button></div>`}
function alternativeReference(ar){const name=alternativeQuery||'Creed Aventus';return `<article class="reference-card"><em>${ar?'العطر المرجعي':'REFERENCE'}</em><img src="assets/alternatives/silver-crest-v1.webp" alt="${name}"><div><span>REFERENCE · EDP · 100ml</span><h2>${name}</h2><small>${ar?'سعر مرجعي تقريبي':'Estimated reference price'}</small><b>${money(11800)}</b></div></article>`}
function alternativeResultCard(item,index,ar){const saving=item.old-item.price,cartId=item.id==='noir'?'alt-noir':item.id==='majestic'?'alt-majestic':'club';return `<article class="alternative-result-card"><i>${index+1}</i><img src="${item.img}" alt="${ar?item.ar:item.name}"><div class="alternative-result-copy"><span>${item.brand}</span><h3>${ar?item.ar:item.name}</h3><div class="alt-rating">★★★★★ <small>${item.rating}</small></div><p>${ar?item.reason:'A close aromatic profile with strong performance and a significantly better price.'}</p></div><div class="match-score"><small>${ar?'نسبة التشابه':'Similarity'}</small><b>${item.match}%</b><span>${ar?'تطابق':'match'}</span></div><div class="performance-mini"><span>${ar?'الثبات':'Longevity'} <b>${item.performance[0]}/10</b></span><i><b style="width:${item.performance[0]*10}%"></b></i><span>${ar?'الفوحان':'Projection'} <b>${item.performance[1]}/10</b></span><i><b style="width:${item.performance[1]*10}%"></b></i></div><div class="alt-price"><small>${ar?'توفر':'Save'} ${money(saving)}</small><b>${money(item.price)}</b><del>${money(item.old)}</del></div><div class="alt-actions"><button data-alt-compare="${item.id}">${uiIcon('eye')} ${ar?'مقارنة':'Compare'}</button><button data-result-add="${cartId}">${uiIcon('bag')} ${ar?'أضف للسلة':'Add to bag'}</button></div></article>`}
function alternativeResultsView(ar){return `${alternativeHeader(ar)}<main class="alternative-results-page"><div class="alternative-title"><span>${uiIcon('sparkles')} ${ar?'نتائج البدائل الذكية':'Smart alternative results'}</span><h1>${ar?'أفضل البدائل المتاحة لعطر':'Best available alternatives for'}<br>${alternativeQuery||'Creed Aventus'}</h1><button data-edit-alternative>${uiIcon('search')} ${ar?'تعديل البحث':'Edit search'}</button></div><div class="reference-and-why">${alternativeReference(ar)}<div><h3>${ar?'لماذا هذه البدائل؟':'Why these alternatives?'}</h3><p>✓ ${ar?'تشابه عالٍ في العائلة العطرية والنوتات':'High similarity in family and notes'}</p><p>✓ ${ar?'أداء قوي من حيث الثبات والفوحان':'Strong longevity and projection'}</p><p>✓ ${ar?'خيارات حصرية ومتاحة في ORIGO':'Exclusive available options'}</p></div></div><div class="alternative-result-list">${alternativeCatalog.map((item,i)=>alternativeResultCard(item,i,ar)).join('')}</div><div class="alternative-alert">${uiIcon('bell')}<div><b>${ar?'لم تجد البديل المناسب؟':'Did not find the right alternative?'}</b><small>${ar?'سنخبرك عند توفر بديل جديد أكثر تطابقاً.':'We will notify you when a closer match becomes available.'}</small></div><button>${ar?'أخبرني':'Notify me'}</button></div></main>`}
function alternativeCompareView(ar){const alt=alternativeCatalog.find(x=>x.id===activeAlternative)||alternativeCatalog[0],saving=alt.old-alt.price,cartId=alt.id==='noir'?'alt-noir':alt.id==='majestic'?'alt-majestic':'club';return `${alternativeHeader(ar)}<main class="alternative-compare-page"><button class="alternative-back" data-alt-back>← ${ar?'العودة للنتائج':'Back to results'}</button><span>${uiIcon('sparkles')} ${ar?'مقارنة البديل المقترح':'Suggested alternative comparison'}</span><h1>${ar?'مقارنة ذكية تساعدك على القرار':'A smart comparison to help you decide'}</h1><div class="comparison-hero"><article><em>${ar?'العطر المرجعي':'Reference'}</em><img src="assets/alternatives/silver-crest-v1.png" alt=""><h2>${alternativeQuery||'Creed Aventus'}</h2><b>${money(alt.old)}</b><small>${ar?'مرجع للمقارنة فقط':'Reference only'}</small></article><div class="comparison-ring"><b>${alt.match}%</b><small>${ar?'نسبة المطابقة':'match'}</small></div><article class="recommended"><em>${ar?'البديل المقترح':'Recommended'}</em><img src="${alt.img}" alt=""><h2>${ar?alt.ar:alt.name}</h2><b>${money(alt.price)}</b><button data-result-add="${cartId}">${uiIcon('bag')} ${ar?'أضف للسلة':'Add to bag'}</button></article></div><div class="comparison-reason"><div><h3>${ar?'سبب الترشيح':'Why we recommend it'}</h3><p>${ar?alt.reason:'A close aromatic profile with excellent performance and value.'}</p></div><div><h3>${ar?'التوفير':'Savings'}</h3><b>${money(saving)}</b><small>${ar?'مقارنة بالسعر المرجعي':'vs. reference price'}</small></div><div><h3>${ar?'الأداء':'Performance'}</h3><p>${ar?'الثبات':'Longevity'} ${alt.performance[0]}/10</p><p>${ar?'الفوحان':'Projection'} ${alt.performance[1]}/10</p></div></div><div class="shared-notes"><h3>${ar?'النوتات المشتركة':'Shared notes'}</h3>${alt.notes.map((n,i)=>`<span>${uiIcon(noteIconName(n,i))}<b>${n}</b></span>`).join('')}</div></main>`}
function renderAlternative(){const ar=currentLang==='ar',root=$('#alternative-content'),markup=alternativeMode==='search'?alternativeSearchView(ar):alternativeMode==='results'?alternativeResultsView(ar):alternativeCompareView(ar);root.innerHTML=markup.replaceAll('silver-crest-v1.png','silver-crest-v1.webp').replaceAll('noir-intense-v1.png','noir-intense-v1.webp').replaceAll('origo-majestic-oud-v1.png','origo-majestic-oud-v1.webp')}
function openAlternative(){closeSurfaces();alternativeMode='search';alternativeQuery='';renderAlternative();const el=$('.alternative-view');el.inert=false;el.classList.add('open');el.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';setTimeout(()=>el.querySelector('input')?.focus(),30)}
function closeAlternative(){const el=$('.alternative-view');el.classList.remove('open');el.setAttribute('aria-hidden','true');el.inert=true;document.body.style.overflow=''}
const applyLanguageAlternativeBase=applyLanguage;
applyLanguage=function(lang){applyLanguageAlternativeBase(lang);if($('.alternative-view').classList.contains('open'))renderAlternative()}
document.addEventListener('submit',e=>{if(!e.target.matches('[data-alternative-search]'))return;e.preventDefault();alternativeQuery=e.target.querySelector('input').value.trim()||'Creed Aventus';alternativeMode='results';renderAlternative()});
document.addEventListener('input',e=>{if(!e.target.closest('[data-alternative-search]'))return;alternativeQuery=e.target.value;renderAlternative();const input=$('[data-alternative-search] input');input?.focus();input?.setSelectionRange(alternativeQuery.length,alternativeQuery.length)});
document.addEventListener('click',e=>{if(e.target.closest('.alternative-view [data-open-quiz]'))closeAlternative();if(e.target.closest('[data-open-alternative]'))openAlternative();if(e.target.closest('[data-close-alternative]'))closeAlternative();const query=e.target.closest('[data-alt-query]');if(query){alternativeQuery=query.dataset.altQuery;alternativeMode='results';renderAlternative()}if(e.target.closest('[data-alt-submit]')){alternativeMode='results';renderAlternative()}if(e.target.closest('[data-edit-alternative]')){alternativeMode='search';renderAlternative()}const compare=e.target.closest('[data-alt-compare]');if(compare){activeAlternative=compare.dataset.altCompare;alternativeMode='compare';renderAlternative()}if(e.target.closest('[data-alt-back]')){alternativeMode='results';renderAlternative()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.alternative-view').classList.contains('open'))closeAlternative()});
const details={
 ar:{asad:{desc:'عطر شرقي واثق يجمع الفلفل الأسود والأناناس مع قلب دافئ من القهوة والتبغ.',notes:['فلفل أسود','قهوة','فانيليا']},club:{desc:'افتتاحية حمضية نابضة تتدرج إلى قلب مدخن وقاعدة خشبية ثابتة ولافتة.',notes:['ليمون','بتولا','مسك']},khamrah:{desc:'توليفة شرقية غنية بالقرفة والتمر والفانيليا، مثالية للأمسيات والطقس البارد.',notes:['قرفة','تمر','فانيليا']},caprice:{desc:'مزيج عطري أنيق يجمع الانتعاش العطري مع الخزامى والأخشاب الناعمة.',notes:['لافندر','هيل','أخشاب']},naque:{desc:'عطر نظيف ومتوازن بنفحات خشبية وعنبرية تمنح حضورًا راقيًا طوال اليوم.',notes:['برغموت','عنبر','أخشاب']},fakhar:{desc:'توقيع عطري مشرق وفاخر يجمع الزهور البيضاء مع الفواكه والأخشاب الناعمة.',notes:['زهر البرتقال','تفاح','خشب']},benefits:['أصلي 100%','توصيل سريع','إرجاع سهل']},
 en:{asad:{desc:'A confident oriental scent blending black pepper and pineapple with warm coffee and tobacco.',notes:['Black pepper','Coffee','Vanilla']},club:{desc:'A vibrant citrus opening that develops into a smoky heart and a long-lasting woody base.',notes:['Lemon','Birch','Musk']},khamrah:{desc:'A rich oriental blend of cinnamon, dates and vanilla, ideal for evenings and cooler weather.',notes:['Cinnamon','Dates','Vanilla']},caprice:{desc:'An elegant aromatic composition combining freshness, lavender and polished soft woods.',notes:['Lavender','Cardamom','Woods']},naque:{desc:'A clean, balanced fragrance with woody amber notes and refined all-day presence.',notes:['Bergamot','Amber','Woods']},fakhar:{desc:'A bright, luxurious signature combining white florals, crisp fruit and smooth woods.',notes:['Orange blossom','Apple','Woods']},benefits:['100% authentic','Fast delivery','Easy returns']}
};
function syncOverlay(){const open=['.cart-drawer','.favorites-drawer','.filter-drawer','.quiz-modal','.product-modal','.compare-modal','.account-modal'].some(s=>$(s)?.classList.contains('open'));$('.overlay').classList.toggle('show',open);document.body.style.overflow=open?'hidden':''}
function closeSurfaces(except=''){if(except!=='cart')closeCart();if(except!=='quiz')closeQuiz();if(except!=='favorites')closeFavorites();if(except!=='filters')closeFilters();if(except!=='product')closeProduct();if(except!=='compare')closeCompare();if(except!=='account')closeAccount()}
function renderFavorites(){const list=[...favorites].map(id=>products.find(p=>p.id===id)).filter(Boolean);$('#favorites-summary').textContent=currentLang==='ar'?`${list.length} منتجات`:`${list.length} items`;$('#favorites-items').innerHTML=list.map(p=>{const label=currentLang==='ar'?p.ar:p.name;return `<article class="favorite-item"><img src="assets/products/${p.img}" alt="${label}" data-quick="${p.id}"><div><span class="product-brand">${p.brand}</span><h4>${label}</h4><p>EDP · 100ml · ★ ${p.rating}</p><b>${money(p.price)}</b><div class="favorite-actions"><button class="add-favorite" data-add="${p.id}">${currentLang==='ar'?'أضف للسلة':'Add to bag'}</button><button class="remove-favorite" data-wish="${p.id}">${currentLang==='ar'?'إزالة':'Remove'}</button></div></div></article>`}).join('');$('#empty-favorites').style.display=list.length?'none':'block'}
function openFavorites(){closeSurfaces('favorites');renderFavorites();const el=$('.favorites-drawer');el.inert=false;el.classList.add('open');el.setAttribute('aria-hidden','false');syncOverlay();setTimeout(()=>el.querySelector('button')?.focus(),30)}
function closeFavorites(){const el=$('.favorites-drawer');el.classList.remove('open');el.setAttribute('aria-hidden','true');el.inert=true;syncOverlay()}
function renderFilterForm(){const ar=currentLang==='ar',form=$('#catalog-filter-form');form.innerHTML=`<div class="filter-form-inner"><section class="filter-group"><h3>${uiIcon('perfume')}${ar?'الماركة':'Brand'}</h3><div class="filter-options"><label><input type="radio" name="brand" value="" ${!catalogFilters.brand?'checked':''}>${ar?'كل الماركات':'All brands'}<span>6</span></label><label><input type="radio" name="brand" value="LATTAFA" ${catalogFilters.brand==='LATTAFA'?'checked':''}>LATTAFA<span>5</span></label><label><input type="radio" name="brand" value="ARMAF" ${catalogFilters.brand==='ARMAF'?'checked':''}>ARMAF<span>1</span></label></div></section><section class="filter-group"><h3>${uiIcon('card')}${ar?'نطاق السعر':'Price range'}</h3><div class="price-inputs"><label>${ar?'من':'Min'}<input type="number" name="min" min="0" value="${catalogFilters.min||''}" placeholder="0"></label><label>${ar?'إلى':'Max'}<input type="number" name="max" min="0" value="${catalogFilters.max<99999?catalogFilters.max:''}" placeholder="5000"></label></div></section><section class="filter-group"><h3>${uiIcon('flower')}${ar?'العائلة العطرية':'Fragrance family'}</h3><div class="filter-options"><label><input type="checkbox" name="family" value="oriental">${ar?'شرقي':'Oriental'}<span>4</span></label><label><input type="checkbox" name="family" value="men">${ar?'رجالي':'Men'}<span>4</span></label><label><input type="checkbox" name="family" value="unisex">${ar?'للجنسين':'Unisex'}<span>2</span></label></div></section><section class="filter-group"><h3>${uiIcon('shield')}${ar?'الحد الأدنى للتقييم':'Minimum rating'}</h3><div class="filter-rating">${[0,4,4.5,4.8].map(v=>`<button type="button" data-rating="${v}" class="${catalogFilters.rating===v?'active':''}">${v?v+'★':ar?'الكل':'All'}</button>`).join('')}</div></section></div><footer class="filter-footer"><button type="reset">${ar?'إعادة ضبط':'Reset'}</button><button type="submit">${ar?'عرض النتائج':'Show results'}</button></footer>`}
function openFilters(){closeSurfaces('filters');renderFilterForm();const el=$('.filter-drawer');el.inert=false;el.classList.add('open');el.setAttribute('aria-hidden','false');syncOverlay();setTimeout(()=>el.querySelector('input,button')?.focus(),30)}
function closeFilters(){const el=$('.filter-drawer');if(!el)return;el.classList.remove('open');el.setAttribute('aria-hidden','true');el.inert=true;syncOverlay()}
function renderAccount(mode=signedIn?'profile':'login'){const ar=currentLang==='ar',root=$('#account-content');if(signedIn){root.innerHTML=`<div class="account-heading">${uiIcon('shield')}<div><span>ORIGO MEMBER</span><h2 id="account-title">${ar?'مرحبًا بك في حسابك':'Welcome to your account'}</h2><p>${ar?'أدر طلباتك ومفضّلتك ونقاط المكافآت من مكان واحد.':'Manage orders, wishlist and rewards in one place.'}</p></div></div><div class="account-stat-grid"><div>${uiIcon('bag')}<b>2</b><small>${ar?'طلبات':'Orders'}</small></div><div>${uiIcon('gift')}<b>320</b><small>${ar?'نقطة':'Points'}</small></div><div>${uiIcon('flower')}<b>${favorites.size}</b><small>${ar?'مفضلة':'Saved'}</small></div></div><div class="account-section-head"><h3>${ar?'آخر الطلبات':'Recent orders'}</h3><button data-logout>${ar?'تسجيل الخروج':'Sign out'}</button></div><article class="order-card"><div class="order-icon">${uiIcon('bag')}</div><div><span>#ORIGO-245817</span><h4>${ar?'طلب عطر خمره وكلوب دي نوي':'Khamrah & Club de Nuit order'}</h4><small>${ar?'12 يوليو 2026 · قطعتان':'12 July 2026 · 2 items'}</small></div><div class="order-status"><i></i>${ar?'قيد التجهيز':'Preparing'}</div><b>${money(2400)}</b><button data-track-order>${ar?'تتبع الطلب':'Track order'}</button></article><div class="tracking-panel" hidden><div class="tracking-line"><i class="done"></i><i class="done"></i><i class="active"></i><i></i></div><div class="tracking-labels"><span>${ar?'تم الطلب':'Placed'}</span><span>${ar?'تم التأكيد':'Confirmed'}</span><span>${ar?'قيد التجهيز':'Preparing'}</span><span>${ar?'خرج للتوصيل':'Out for delivery'}</span></div></div>`;return}root.innerHTML=`<div class="account-auth"><div class="account-art">${uiIcon('perfume')}<span>ORIGO SOCIETY</span><h2>${ar?'عالمك العطري الخاص':'Your private fragrance world'}</h2><p>${ar?'احفظ اختياراتك، تابع طلباتك واجمع نقاط المكافآت.':'Save favorites, track orders and collect rewards.'}</p></div><div class="account-form"><div class="account-tabs"><button class="${mode==='login'?'active':''}" data-account-mode="login">${ar?'تسجيل الدخول':'Sign in'}</button><button class="${mode==='register'?'active':''}" data-account-mode="register">${ar?'حساب جديد':'Create account'}</button></div><h2 id="account-title">${mode==='login'?(ar?'مرحبًا بعودتك':'Welcome back'):(ar?'انضم إلى ORIGO':'Join ORIGO')}</h2><p>${mode==='login'?(ar?'سجّل الدخول للوصول إلى حسابك.':'Sign in to access your account.'):(ar?'أنشئ حسابًا خلال لحظات.':'Create your account in moments.')}</p><form id="account-form">${mode==='register'?`<div class="field"><label>${ar?'الاسم الكامل':'Full name'}</label><input name="name" required></div>`:''}<div class="field"><label>${ar?'البريد الإلكتروني':'Email address'}</label><input type="email" name="email" required></div><div class="field"><label>${ar?'كلمة المرور':'Password'}</label><input type="password" name="password" minlength="6" required></div><button class="btn btn-wine" type="submit">${mode==='login'?(ar?'تسجيل الدخول':'Sign in'):(ar?'إنشاء الحساب':'Create account')}</button></form><div class="auth-benefits"><span>${uiIcon('shield')} ${ar?'بياناتك محمية':'Your data is protected'}</span><span>${uiIcon('gift')} ${ar?'نقاط مع كل طلب':'Rewards on every order'}</span></div></div></div>`;wireAccountLabels()}
function wireAccountLabels(){$$('#account-form .field').forEach((field,i)=>{const control=field.querySelector('input'),label=field.querySelector('label');control.id=`account-field-${i}`;label.htmlFor=control.id})}
function openAccount(){closeSurfaces('account');renderAccount();const el=$('.account-modal');el.inert=false;el.classList.add('open');el.setAttribute('aria-hidden','false');syncOverlay();setTimeout(()=>el.querySelector('button')?.focus(),30)}
function closeAccount(){const el=$('.account-modal');if(!el)return;el.classList.remove('open');el.setAttribute('aria-hidden','true');el.inert=true;syncOverlay()}
function renderProduct(id){const p=products.find(x=>x.id===id);if(!p)return;activeProductId=id;const d=details[currentLang][id],label=currentLang==='ar'?p.ar:p.name;$('#product-modal-content').innerHTML=`<div class="product-detail-grid"><div class="product-detail-gallery"><span class="product-detail-badge">${badgeText(p)}</span><img src="assets/products/${p.img}" alt="${label}"></div><div class="product-detail-info"><span class="product-brand">${p.brand}</span><h2 id="product-modal-title">${label}</h2><div class="product-detail-en">${currentLang==='ar'?p.name:p.ar}</div><div class="detail-rating">★★★★★ <span>${p.rating} (${p.reviews})</span></div><p class="detail-description">${d.desc}</p><div class="detail-price"><b>${money(p.price)}</b>${p.old?`<del>${money(p.old)}</del>`:''}</div><h3>${currentLang==='ar'?'الحجم المتاح':'Available size'}</h3><div class="detail-size"><button class="active" type="button">100ml</button></div><div class="detail-cta"><button class="btn btn-wine" data-add="${p.id}">${currentLang==='ar'?'أضف للسلة':'Add to bag'} <span>＋</span></button><button class="detail-wish ${favorites.has(p.id)?'active':''}" data-wish="${p.id}" aria-label="${currentLang==='ar'?'إضافة للمفضلة':'Add to wishlist'}">${favorites.has(p.id)?'♥':'♡'}</button></div><div class="detail-benefits">${details[currentLang].benefits.map((x,i)=>`<div><b>${['♢','▱','↻'][i]} ${x}</b><small>${currentLang==='ar'?['مضمون ومعتمد','لكل محافظات مصر','خلال 14 يومًا'][i]:['Guaranteed','Across Egypt','Within 14 days'][i]}</small></div>`).join('')}</div><div class="notes-panel"><h3>${currentLang==='ar'?'النوتات الرئيسية':'Key notes'}</h3><div class="notes-row">${d.notes.map((n,i)=>`<div class="note-pill"><span>${['✦','♨','❧'][i]}</span>${n}</div>`).join('')}</div></div></div></div>`}
const renderProductTextBase=renderProduct;
