function checkoutLabels(){return currentLang==='ar'?{steps:['السلة','العنوان','الدفع','تأكيد الطلب'],placed:'تم الطلب',secure:'دفع آمن ومشفّر',summary:'ملخص الطلب',subtotal:'المجموع الفرعي',shipping:'الشحن',total:'الإجمالي',free:'مجاني'}:{steps:['Bag','Address','Payment','Review & confirm'],placed:'Order placed',secure:'Secure encrypted payment',summary:'Order summary',subtotal:'Subtotal',shipping:'Shipping',total:'Total',free:'Free'}}
function renderCheckoutProgress(){const l=checkoutLabels(),active=Math.min(checkoutStep+1,4),steps=[...l.steps];if(checkoutStep===4)steps[3]=l.placed;$('#checkout-progress').innerHTML=`<div class="checkout-steps">${steps.map((s,i)=>`<div class="checkout-step ${active===i+1?'active':''} ${active>i+1?'done':''}"><span>${active>i+1?'✓':i+1}</span>${s}</div>`).join('')}</div>`;$('.secure-label b').textContent=l.secure}
