function translateLooseText(lang){const reverse=Object.fromEntries(Object.entries(autoText).map(([ar,en])=>[en,ar]));const map=lang==='en'?autoText:reverse;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(['SCRIPT','STYLE'].includes(node.parentElement?.tagName))continue;const raw=node.nodeValue,trim=raw.trim();if(map[trim])node.nodeValue=raw.replace(trim,map[trim])}}
function applyLanguage(lang){currentLang=lang;localStorage.setItem('origo-lang',lang);document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=lang==='ar'?'ORIGO | اكتشف عطرك المثالي':'ORIGO | Discover your perfect scent';$$('[data-i18n]').forEach(el=>{const value=i18n[lang][el.dataset.i18n];if(value)el.textContent=value});translateLooseText(lang);$('.lang-toggle b').textContent=lang==='ar'?'EN':'ع';$('#search-input').placeholder=lang==='ar'?'ابحث عن عطر، ماركة، أو نوتة...':'Search by fragrance, brand or note...';renderProducts($('.product-tabs .active')?.dataset.filter||'all',$('#search-input').value);renderCart();renderFavorites();updateCompareTray();if($('.quiz-modal').classList.contains('open'))quizView();if($('.product-modal').classList.contains('open')&&activeProductId)renderProduct(activeProductId);if($('.compare-modal').classList.contains('open'))renderCompare();if($('.checkout-view').classList.contains('open'))renderCheckout()}
