applyLanguage=function(lang){applyLanguageAccountBase(lang);if($('.account-modal').classList.contains('open'))renderAccount()}
function updateCatalogLanguage(){const ar=currentLang==='ar',toolbar=$('.catalog-toolbar');if(!toolbar)return;toolbar.querySelector('label').textContent=ar?'ترتيب حسب':'Sort by';toolbar.querySelector('button span').textContent=ar?'تصفية':'Filters';const options=$$('#catalog-sort option'),labels=ar?['الأكثر تميزًا','السعر: الأقل أولًا','السعر: الأعلى أولًا','الأعلى تقييمًا']:['Featured','Price: low to high','Price: high to low','Top rated'];options.forEach((o,i)=>o.textContent=labels[i]);if($('.filter-drawer').classList.contains('open'))renderFilterForm()}
