function applyTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('origo-theme',theme);$('.theme-icon use').setAttribute('href',theme==='dark'?'#i-sun':'#i-moon');$('.theme-toggle').setAttribute('aria-label',theme==='dark'?(currentLang==='ar'?'تفعيل الوضع النهاري':'Switch to light mode'):(currentLang==='ar'?'تفعيل الوضع الليلي':'Switch to dark mode'))}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add],.quick-add,[data-result-add]');if(add)addToCart(add.dataset.add||add.dataset.id||add.dataset.resultAdd);const wish=e.target.closest('[data-wish]');if(wish){const id=wish.dataset.wish;favorites.has(id)?favorites.delete(id):favorites.add(id);persist();wish.classList.toggle('active');wish.textContent=favorites.has(id)?'♥':'♡';$$('.fav-count').forEach(x=>x.textContent=favorites.size);toast(favorites.has(id)?(currentLang==='ar'?'أضيف إلى المفضلة':'Added to wishlist'):(currentLang==='ar'?'أزيل من المفضلة':'Removed from wishlist'))}const rem=e.target.closest('[data-remove]');if(rem){cart=cart.filter(x=>x.id!==rem.dataset.remove);persist();renderCart()}if(e.target.closest('[data-open-cart]'))openCart();if(e.target.closest('[data-close-cart]'))closeCart();if(e.target.closest('[data-open-quiz]'))openQuiz();if(e.target.closest('[data-close-quiz]'))closeQuiz();if(e.target.closest('[data-close-all]')){closeCart();closeQuiz()}if(e.target.closest('[data-lang-toggle]'))applyLanguage(currentLang==='ar'?'en':'ar');if(e.target.closest('[data-theme-toggle]'))applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');const ans=e.target.closest('[data-answer]');if(ans){answers.push(+ans.dataset.answer);quizStep++;quizView()}const tab=e.target.closest('[data-filter]');if(tab){$$('[data-filter]').forEach(x=>x.classList.remove('active'));tab.classList.add('active');renderProducts(tab.dataset.filter,$('#search-input').value)}if(e.target.closest('[data-open-menu]')){$('#search-input').closest('.search').classList.toggle('mobile-open');setTimeout(()=>$('#search-input').focus(),100)}});
document.addEventListener('click',e=>{const quick=e.target.closest('[data-quick]');if(quick){e.preventDefault();openProduct(quick.dataset.quick)}if(e.target.closest('[data-favorites]'))openFavorites();if(e.target.closest('[data-close-favorites]'))closeFavorites();if(e.target.closest('[data-close-product]'))closeProduct();if(e.target.closest('[data-open-compare]'))openCompare();if(e.target.closest('[data-close-compare]'))closeCompare();if(e.target.closest('[data-clear-compare]')){compareIds.clear();$$('[data-compare]').forEach(x=>x.checked=false);updateCompareTray()}if(e.target.closest('[data-checkout]'))openCheckout();if(e.target.closest('[data-close-checkout]'))closeCheckout();if(e.target.closest('[data-checkout-prev]')){checkoutStep=Math.max(1,checkoutStep-1);renderCheckout()}if(e.target.closest('[data-finish-checkout]'))closeCheckout();if(e.target.closest('[data-close-all]')){closeFavorites();closeProduct();closeCompare()}if(e.target.closest('[data-wish]')){if($('.favorites-drawer').classList.contains('open'))renderFavorites();if(activeProductId)renderProduct(activeProductId)}});
