document.addEventListener('click',e=>{const tab=e.target.closest('[role="tab"]');if(tab)$$('[role="tab"]').forEach(x=>x.setAttribute('aria-selected',String(x===tab)))});
$('.product-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;const tabs=$$('[role="tab"]'),current=tabs.indexOf(document.activeElement);if(current<0)return;e.preventDefault();const delta=e.key==='ArrowLeft'?1:-1,tabsCount=tabs.length,next=tabs[(current+delta+tabsCount)%tabsCount];next.focus();next.click()});
document.addEventListener('submit',e=>{if(e.target.id!=='checkout-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.assign(checkoutData,data);if(checkoutStep===1){checkoutStep=2;renderCheckout()}else if(checkoutStep===2){checkoutStep=3;renderCheckout()}});
