document.addEventListener('click',e=>{if(e.target.closest('[data-account]'))openAccount();const brand=e.target.closest('[data-brand]');if(brand){$('#search-input').value=brand.dataset.brand;renderProducts('all',brand.dataset.brand);$('#products').scrollIntoView({behavior:'smooth'});$$('[data-brand]').forEach(x=>x.classList.toggle('featured',x===brand))}});
document.addEventListener('click',e=>{if(e.target.closest('[data-close-account]'))closeAccount();const mode=e.target.closest('[data-account-mode]');if(mode)renderAccount(mode.dataset.accountMode);if(e.target.closest('[data-logout]')){signedIn=false;localStorage.removeItem('origo-user');renderAccount('login')}const track=e.target.closest('[data-track-order]');if(track){const panel=$('.tracking-panel');panel.hidden=!panel.hidden;track.textContent=panel.hidden?(currentLang==='ar'?'تتبع الطلب':'Track order'):(currentLang==='ar'?'إخفاء التتبع':'Hide tracking')}const qty=e.target.closest('[data-qty]');if(qty){const item=cart.find(x=>x.id===qty.dataset.qty);if(item){item.qty+=Number(qty.dataset.delta);if(item.qty<=0)cart=cart.filter(x=>x.id!==item.id);persist();renderCart()}}if(e.target.closest('[data-apply-promo]')){const code=$('#promo-input')?.value.trim().toUpperCase();if(code==='ORIGO10'){const subtotal=cart.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0);promoDiscount=Math.round(subtotal*.1);renderCart();toast(currentLang==='ar'?'تم تطبيق الكوبون بنجاح':'Promo code applied')}else toast(currentLang==='ar'?'الكود غير صالح أو منتهي':'This code is invalid or expired')}if(e.target.closest('[data-redeem-points]')){promoDiscount=Math.max(promoDiscount,100);renderCart();toast(currentLang==='ar'?'تم استبدال 200 نقطة بخصم 100 ج.م':'200 points redeemed for 100 EGP off')}if(e.target.closest('[data-close-all]'))closeAccount()});
document.addEventListener('change',e=>{if(e.target.name!=='payment')return;const fields=$('[data-card-fields]'),card=e.target.value==='card';if(fields){fields.hidden=!card;$$('input',fields).forEach(input=>{input.disabled=!card;input.required=card})}});
