document.addEventListener('click',e=>{if(e.target.closest('[data-open-filters]'))openFilters();if(e.target.closest('[data-close-filters]'))closeFilters();const rating=e.target.closest('[data-rating]');if(rating){catalogFilters.rating=Number(rating.dataset.rating);$$('[data-rating]').forEach(x=>x.classList.toggle('active',x===rating))}if(e.target.closest('[data-close-all]'))closeFilters()});
