$('#search-input').addEventListener('keydown',e=>{const items=$$('.suggestion-item'),current=items.findIndex(x=>x.classList.contains('active'));if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items.forEach(x=>x.classList.remove('active'));const next=e.key==='ArrowDown'?(current+1)%Math.max(1,items.length):(current<=0?items.length-1:current-1);items[next]?.classList.add('active');items[next]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&current>=0){e.preventDefault();items[current].click()}});
document.addEventListener('click',e=>{const term=e.target.closest('[data-search-term]');if(term){$('#search-input').value=term.dataset.searchTerm;renderProducts('all',term.dataset.searchTerm);renderSearchSuggestions(term.dataset.searchTerm)}if(e.target.closest('[data-clear-searches]')){recentSearches=[];localStorage.removeItem('origo-searches');renderSearchSuggestions('')}const suggestion=e.target.closest('.suggestion-item');if(suggestion){const text=suggestion.querySelector('b')?.textContent;if(text){recentSearches=[text,...recentSearches.filter(x=>x!==text)].slice(0,5);localStorage.setItem('origo-searches',JSON.stringify(recentSearches))}closeSearchSuggestions()}else if(!e.target.closest('.search'))closeSearchSuggestions()});
